#!/usr/bin/env node
/**
 * 一次性修复工具（wb.6）：清理宿主提示词模板里堆积的重复 GENERATED 头。
 *
 * 症状：`cli-agent-prompt` / `*.tpl` 开头有一长串完全相同的
 * `<!-- GENERATED by build/generate.mjs … -->` 注释。成因见 hooks/selfpatch.mjs
 * 的 collapseHeaders() 注释 —— wb.5 及以前每跑一次 SessionStart 就多留一行，
 * 一百多个会话后能堆到 327 行（模板 19.8k → 45k 字符），白烧 token。
 *
 * 用法：
 *   node tools/fix-header-dupes.mjs --dry-run     # 只报告，不写
 *   node tools/fix-header-dupes.mjs               # 备份后修复
 *   node tools/fix-header-dupes.mjs --app-dir "H:\Program Files\WorkBuddy"
 *
 * 备份：<configDir>/dsh-purge/backup/pre-headerfix-<时间戳>/（含 manifest.json）
 * 幂等：正常模板（每个载荷一条头）不会被改写。
 */
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

const argv = process.argv.slice(2);
const DRY = argv.includes('--dry-run');
const appDirArg = (() => {
  const i = argv.indexOf('--app-dir');
  return i >= 0 ? argv[i + 1] : null;
})();

const cfgDir = process.env.WORKBUDDY_CONFIG_DIR || process.env.CODEBUDDY_CONFIG_DIR
  || path.join(os.homedir(), '.workbuddy');
const stateDir = path.join(cfgDir, 'dsh-purge');

const GEN_HEADER = '<!-- GENERATED by build/generate.mjs — 修改请改 contract/ 后重跑 npm run build -->';
const GEN_HEADER_RE = /<!--\s*GENERATED by build\/generate\.mjs[^>]*-->/g;
const GEN_HEADER_ANY = /<!--\s*GENERATED by build\/generate\.mjs[^>]*-->/;

function collapseHeaders(t) {
  return t.replace(/(?:<!--\s*GENERATED by build\/generate\.mjs[^>]*-->\s*){2,}/g, `${GEN_HEADER}\n\n`);
}

const countHeaders = (t) => (t.match(GEN_HEADER_RE) || []).length;

function readJson(file, fallback) {
  try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return fallback; }
}

function findAppDir() {
  if (appDirArg && fs.existsSync(appDirArg)) return appDirArg;
  if (process.env.DSH_PURGE_APP_DIR && fs.existsSync(process.env.DSH_PURGE_APP_DIR)) {
    return process.env.DSH_PURGE_APP_DIR;
  }
  const known = readJson(path.join(cfgDir, 'plugins', 'known_marketplaces.json'), {});
  for (const entry of Object.values(known || {})) {
    const p = entry?.installLocation || entry?.source?.path;
    if (typeof p === 'string') {
      const m = p.match(/^(.*?)[\\/]resources[\\/]app\.asar\.unpacked/i);
      if (m) return m[1];
    }
  }
  for (const g of [
    'D:\\001installation_package\\WorkBuddy',
    'D:\\installation package\\WorkBuddy',
    path.join(process.env.LOCALAPPDATA || '', 'Programs', 'WorkBuddy'),
    path.join(process.env.ProgramFiles || 'C:\\Program Files', 'WorkBuddy'),
  ]) {
    if (g && fs.existsSync(path.join(g, 'WorkBuddy.exe'))) return g;
  }
  return null;
}

function walkTpls(root, out) {
  let entries = [];
  try { entries = fs.readdirSync(root, { withFileTypes: true }); } catch { return; }
  for (const e of entries) {
    const full = path.join(root, e.name);
    if (e.isDirectory()) { walkTpls(full, out); continue; }
    if (!e.name.endsWith('.tpl')) continue;
    try { if (GEN_HEADER_ANY.test(fs.readFileSync(full, 'utf8'))) out.push(full); } catch { /* ignore */ }
  }
}

// ── 收集目标 ────────────────────────────────────────────────────────────
const appDir = findAppDir();
const productTargets = [];
if (appDir) {
  const unpacked = path.join(appDir, 'resources', 'app.asar.unpacked');
  for (const p of [
    path.join(unpacked, 'cli', 'product.json'),
    path.join(unpacked, 'node_modules', '@genie', 'agent-harness', 'cli', 'product.json'),
  ]) if (fs.existsSync(p)) productTargets.push(p);
}

const tplTargets = [];
if (appDir) {
  walkTpls(path.join(appDir, 'resources', 'app.asar.unpacked', 'resources'), tplTargets);
}
walkTpls(path.join(cfgDir, 'plugins', 'cache'), tplTargets);

console.log(`config dir : ${cfgDir}`);
console.log(`app dir    : ${appDir || '未定位（只处理插件缓存里的 tpl）'}`);
console.log(`mode       : ${DRY ? 'dry-run（不写盘）' : 'apply'}`);

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupRoot = path.join(stateDir, 'backup', `pre-headerfix-${stamp}`);
const manifest = [];
const results = [];

function backup(file) {
  if (DRY) return;
  let rel;
  if (appDir && file.startsWith(appDir)) rel = path.join('__app__', path.relative(appDir, file));
  else rel = path.join('__config__', path.relative(cfgDir, file));
  const dst = path.join(backupRoot, rel);
  fs.mkdirSync(path.dirname(dst), { recursive: true });
  fs.copyFileSync(file, dst);
  manifest.push({ from: file, to: dst });
}

// ── product.json ────────────────────────────────────────────────────────
for (const file of productTargets) {
  const j = readJson(file, null);
  if (!j || !Array.isArray(j.prompts)) { results.push({ file, skip: 'JSON 解析失败或无 prompts' }); continue; }
  const tpl = j.prompts.find((p) => p && p.name === 'cli-agent-prompt');
  if (!tpl || typeof tpl.template !== 'string') { results.push({ file, skip: '无 cli-agent-prompt' }); continue; }
  const before = { headers: countHeaders(tpl.template), length: tpl.template.length };
  const next = collapseHeaders(tpl.template);
  const after = { headers: countHeaders(next), length: next.length };
  if (next !== tpl.template) {
    backup(file);
    if (!DRY) {
      tpl.template = next;
      fs.writeFileSync(file, `${JSON.stringify(j, null, 2)}\n`, 'utf8');
    }
  }
  results.push({ file, before, after, written: next !== tpl.template && !DRY });
}

// ── .tpl ────────────────────────────────────────────────────────────────
for (const file of tplTargets) {
  let t;
  try { t = fs.readFileSync(file, 'utf8'); } catch { continue; }
  const before = { headers: countHeaders(t), length: t.length };
  const next = collapseHeaders(t);
  const after = { headers: countHeaders(next), length: next.length };
  if (next !== t) {
    backup(file);
    if (!DRY) fs.writeFileSync(file, next, 'utf8');
  }
  results.push({ file, before, after, written: next !== t && !DRY });
}

if (!DRY && manifest.length) {
  fs.mkdirSync(backupRoot, { recursive: true });
  fs.writeFileSync(path.join(backupRoot, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`, 'utf8');
}

// ── 报告 ────────────────────────────────────────────────────────────────
let dirty = 0;
let saved = 0;
for (const r of results) {
  if (r.skip) { console.log(`  SKIP ${r.file}（${r.skip}）`); continue; }
  const { before, after } = r;
  const changed = after.headers !== before.headers || after.length !== before.length;
  if (changed) dirty += 1;
  saved += Math.max(0, before.length - after.length);
  console.log(`  ${changed ? (r.written ? 'FIX ' : 'TODO') : 'ok  '} headers ${before.headers}→${after.headers}  len ${before.length}→${after.length}  ${r.file}`);
}
console.log(`targets=${results.length} dirty=${dirty} bytesSaved=${saved}${DRY ? '（dry-run，未写盘）' : ''}`);
if (!DRY && manifest.length) console.log(`备份：${backupRoot}`);
if (DRY && dirty) console.log('确认无误后去掉 --dry-run 再跑一次；之后重启 WorkBuddy 让新模板生效。');
